begin;
do $$ declare v uuid; t timestamptz:=now(); begin
select id into strict v from books where lower(title)=lower('Owl Moon');
delete from writing_trait_annotations where book_id=v; delete from reading_strategy_annotations where book_id=v; delete from pride_value_annotations where book_id=v; delete from inquiry_lens_annotations where book_id=v; delete from teaching_ideas where book_id=v; delete from why_use_bullets where book_id=v; delete from teaching_resources where book_id=v;
insert into writing_trait_annotations(book_id,trait_slug,year_level,in_this_book_text,applicable_year_levels,source_type,source_name,confidence,status,reviewed_by,reviewed_at,key_understanding_text,key_skill_text,display_order) select v,slug,yr,txt,yr,'ai_suggested','Ngarri curriculum and complete-text review','high','teacher_reviewed','Phill',t,ku,ks,ord from jsonb_to_recordset($json$[{"slug":"ideas","yr":"Year 1","ku":"I need knowledge of my idea/s to include detail in my writing. This knowledge can be developed through mentor texts, experiences","ks":"I can include supportive descriptions, details or examples to explain the important ideas in my writing.","txt":"Yolen develops one small experience rather than adding several events. The narrator notices the train whistle, singing dogs, footprints, shadows, the wet scarf, the cold on their cheeks and the heat of their breath. These carefully selected details let students see how close observation and remembered experience can make a simple journey feel complete.","ord":1},{"slug":"organisation","yr":"Year 3","ku":"writer's can varying pacing in their writing e.g to 'stretch out' a moment in my writing (spotlight) and when to speed through a moment.","ks":"I can include spotlights and speed throughs in my text to highlight key ideas and pace.","txt":"The walk is compressed through a sequence of sensory impressions, but each owl call is stretched by line breaks, repetition and waiting. The sighting slows further: the shadow crosses the ground, the owl lands, child and owl stare at one another, and a minute feels extraordinarily long. Students can trace how this deliberate deceleration spotlights the experience the whole journey has prepared.","ord":2},{"slug":"word_choice","yr":"Year 2","ku":"word choices enhance the reader's experience","ks":"I can experiment with simple figurative language.","txt":"The narrator explains unfamiliar sensations through comparisons a young reader can picture: trees stand like statues, the train sounds like a sad song, quiet feels like a dream and cold presses like an icy hand. Students can identify the exact sensory quality carried by each comparison, then create a simile that clarifies a real observation rather than decorating it.","ord":3},{"slug":"word_choice","yr":"Year 4","ku":"word choice can help my reader visualise my ideas","ks":"I can use specific words to encourage my reader to visualise.","txt":"Specific verbs and colour contrasts construct the winter night: feet crunch, shadows stain the snow, twigs snap, an owl's shadow floats and the bird disappears without sound. The language tells readers what can be heard, seen and felt while leaving space for imagination. Students can replace general movement or sound words in a setting description with a few precise choices that establish place and mood.","ord":4},{"slug":"sentence_fluency","yr":"Year 2","ku":"varying the start, structure and length of sentences enhances the reader's experience","ks":"I can experiment with different length sentences for effect.","txt":"Long flowing sentences carry the pair through the landscape, while brief statements interrupt the movement: there is no answer, they walk on, and the child does not speak. The repeated conditional beginning about going owling creates a quiet refrain. Students can read a passage aloud and hear how short sentences hold the silence while longer ones carry observation and movement.","ord":5},{"slug":"voice_audience","yr":"Year 2","ku":"writing can capture a general mood and evoke emotions such as joy, fear, excitement and humour.","ks":"I can explain and justify ways I can engage my audience (e.g interesting leads, word choice, onomatopoeia, persuasive devices etc).","txt":"The child never announces every emotion. Anticipation emerges through having waited a long time; fear through unasked questions about the black trees; courage through continuing silently; wonder through the altered sense of time when the owl appears. This restrained voice invites the audience to feel alongside the narrator instead of being told what to feel.","ord":6},{"slug":"presentation","yr":"Year 4","ku":"what 'white space' is and how to frame my text appropriately.","ks":"I can include relevant illustrations, labelled diagrams, graphs, charts or tables to enhance my writing.","txt":"Schoenherr repeatedly changes the balance of dark image and pale open space. Looming trunks frame small human figures during the search; an enormous owl wing fills the arrival spread; the final walk home leaves the figures tiny within white space. Students can explain how scale, framing and empty space control attention and emotional intensity, then plan a spread whose composition adds meaning not already stated in its words.","ord":7}]$json$::jsonb) x(slug text,yr text,ku text,ks text,txt text,ord int);
insert into reading_strategy_annotations(book_id,strategy_slug,year_level,in_this_book_text,applicable_year_levels,source_type,source_name,confidence,status,reviewed_by,reviewed_at,key_understanding_text,key_skill_text,display_order) select v,slug,yr,txt,yr,'ai_suggested','Ngarri curriculum and complete-text review','high','teacher_reviewed','Phill',t,ku,ks,ord from jsonb_to_recordset($json$[{"slug":"inferring","yr":"Foundation","ku":"Clues within a text are needed to infer the emotions of a character","ks":"I can infer the emotions of a character using pictures and words (happy, sad, angry, excited, tired).","txt":"The child does not say, \"I was excited.\" Waiting a long time to go, hurrying to keep up and remaining quiet despite the cold provide word clues; the close positioning beside Pa and the final small figures walking home provide visual clues. Students can combine one clue from each mode to infer anticipation, nervousness or happiness.","ord":1},{"slug":"inferring","yr":"Year 1","ku":"Inferring is when we work out what the author doesn't exactly say.","ks":"I can infer character feelings using text clues such as pictures and words.","txt":"When no owl answers, Pa and the child both shrug, and the child insists they are not disappointed. Their continued searching, Pa's near-smile at the later response and the child's close attention suggest that the experience matters deeply. Students can discuss the difference between what the narrator says directly and what actions, repetition and illustrations allow them to infer.","ord":2},{"slug":"inferring","yr":"Year 3","ku":"Using a range of text clues can help me make predictions and inferences.","ks":"I can use a range of text clues to make predictions/inferences including pictures, graphics, past storyline,","txt":"The relationship with Pa is built without conversation. He prepares the child's clothing, sets the pace, signals when to stop, teaches the rules of owling and shares the final gaze. The child follows his example and recalls what he and the older brothers have said. Students can combine action, remembered speech, proximity in the pictures and the shared silence to infer trust, teaching and companionship.","ord":3},{"slug":"synthesising","yr":"Year 2","ku":"That synthesis is when we use our prior knowledge and the text to build deeper understandings. (Synthesising)","ks":"I can identify how the new knowledge developed my thinking. (synthesising)","txt":"Readers may begin by thinking that a successful trip must end with finding an owl. The repeated possibility that there may be no owl, followed by the final statement that hope is enough, develops a broader understanding: the patient shared experience matters even when nature cannot be controlled. Students can record how their idea of a \"successful\" outing changes across the search.","ord":4},{"slug":"making_connections","yr":"Year 4","ku":"Connections can help us develop a deeper understanding of texts","ks":"I can make connections (text to text and text to world) to compare perspectives, ideas, characterization and literacy devices.","txt":"Students can connect the child's first owling trip with a tradition, skill or special place introduced by someone in their own family or community, then compare the purpose of silence, patience and observation in both experiences. A text-to-world connection with ethical wildlife watching can deepen discussion of why Pa calls and waits rather than chasing or handling the owl.","ord":5},{"slug":"analysing","yr":"Year 4","ku":"Different text types have typical stages and language features dependent on their purpose.","ks":"I can explain how author's use different literary devices to add to the meaning of the text. (grammar, word choices, free verse, symbolism, personification, metaphor etc.)","txt":"Moonlight and shadow are more than setting details. The moon makes Pa's face a silver mask, shadows stain the snow, and the owl first arrives as a moving shadow before becoming fully visible. Students can analyse how recurring light-and-dark imagery moves the narrative from uncertainty and imagined danger toward recognition and wonder.","ord":6}]$json$::jsonb) x(slug text,yr text,ku text,ks text,txt text,ord int);
insert into pride_value_annotations(book_id,value_slug,in_this_book_text,confidence,status,reviewed_by,reviewed_at,display_order) select v,slug,txt,'high','teacher_reviewed','Phill',t,ord from jsonb_to_recordset($json$[{"slug":"determination","txt":"The child has waited a long time for this first trip and continues through cold, darkness and an unanswered call. Pa also accepts the silence, walks deeper into the woods and tries again rather than demanding an immediate result. Their determination is patient and responsive: they persist while accepting that the owl is a wild animal and success is not guaranteed.","ord":1}]$json$::jsonb) x(slug text,txt text,ord int);
insert into inquiry_lens_annotations(book_id,lens_slug,in_this_book_text,confidence,status,reviewed_by,reviewed_at,display_order) select v,slug,txt,'high','teacher_reviewed','Phill',t,ord from jsonb_to_recordset($json$[{"slug":"identity_creativity_wellbeing","txt":"A first owling trip becomes part of the child's growing identity within a family. The child draws on Pa's guidance and the older brothers' experience, manages fear and discomfort, and discovers they can act with patience and courage. Students can inquire into how shared traditions, trusted relationships and manageable challenges help people develop confidence and belonging.","ord":1},{"slug":"environmental_sustainability","txt":"The pair enter the night environment as quiet observers. They attend to weather, animal calls, tracks, trees and moonlight, use a call and brief torchlight, and allow the owl to leave. Students can investigate how people can experience wildlife with wonder while minimising disturbance, and distinguish the book's respectful actions from practices that would place an animal or habitat under pressure.","ord":2}]$json$::jsonb) x(slug text,txt text,ord int);
insert into teaching_ideas(book_id,title,description,time_minutes,"grouping",difficulty,colour_tag,is_generic,status,year_levels,linked_focus,where_to_look,learning_focus,teaching_sequence,student_application,notice_learning,display_order,reviewed_by,reviewed_at) select v,title,learning,minutes,grouping,difficulty,'green',false,'teacher_reviewed',years,focus,look,learning,sequence,application,notice,ord,'Phill',t from jsonb_to_recordset($json$[{"title":"Infer the feeling without a feeling word","focus":"Inferring; Audience/Voice","years":"Foundation-2","minutes":25,"grouping":"Whole class","difficulty":"Entry","look":"The opening wait to go owling, the first unanswered call and the child's responses to cold and darkness","learning":"Combine actions, narration and illustrations to infer emotion","sequence":"Model noticing an action before naming a feeling; deliberately test an over-simple inference such as \"sad\" against more than one clue; chart what the words show and what the picture adds; invite students to justify or revise the inference","application":"Partners choose one moment and complete: \"The child may feel ___ because the words show ___ and the picture shows ___.\"","notice":"Students use two compatible clues, distinguish inference from guessing and accept more than one defensible feeling","ord":1},{"title":"Collect one small moment","focus":"Ideas","years":"Foundation-2","minutes":35,"grouping":"Individual","difficulty":"Medium","look":"The sensory details gathered during the single walk through the snow","learning":"Develop a familiar experience through selected, observable detail","sequence":"Name the whole event in one sentence; sort details by seeing, hearing, touch and movement; model choosing details that belong to the same moment; remove one attractive but unrelated idea and explain why it weakens the focus","application":"Students draw a familiar small moment, label four sensory or action details, orally rehearse it and write a short focused account","notice":"Details support one central experience rather than becoming a list of disconnected events","ord":2},{"title":"Make a comparison earn its place","focus":"Word Choice","years":"2-4","minutes":30,"grouping":"Whole class","difficulty":"Medium","look":"The comparisons for the trees, train whistle, quiet and cold","learning":"Explain and create figurative language that clarifies a precise quality","sequence":"Identify what is being compared; ask which shared quality the comparison makes vivid; contrast a useful simile with a surprising but inaccurate one; jointly revise a general winter description","application":"Students observe one sound, movement or sensation and draft three comparisons before selecting and justifying the most accurate","notice":"The chosen image sharpens meaning and mood rather than merely using \"like\" or \"as.\"","ord":3},{"title":"Hear the pace change","focus":"Organisation; Sentence Fluency","years":"2-4","minutes":30,"grouping":"Whole class","difficulty":"Medium","look":"A walking passage, the repeated owl calls and the extended sighting","learning":"Use sentence length, repetition and pause to speed or stretch narrative time","sequence":"Read the walk at a natural pace; mark where the call-and-wait pattern forces pauses; think aloud while deciding which part is the true spotlight; compare the short story time of the sighting with the amount of text and visual space it receives","application":"Students revise a brief event so routine movement is compressed and one important instant is expanded through two or three purposeful details and varied sentences","notice":"The slowest writing aligns with the moment the writer wants the reader to experience most intensely","ord":4},{"title":"Read the relationship in the silence","focus":"Inferring","years":"2-4","minutes":35,"grouping":"Small group","difficulty":"Medium","look":"Pa's preparations and signals, the mirrored shrug, the near-smile and the shared observation of the owl","learning":"Infer a relationship from patterns of action and visual proximity","sequence":"Gather evidence without first assigning a trait; revoice a claim such as \"Pa is kind\" as a question about what he does; press for a second clue; compare how the relationship would feel if the pair talked continuously","application":"Groups construct a claim-evidence-explanation strip about what the pair trust, teach or understand without saying aloud","notice":"Students explain how several details build the relationship and avoid treating one isolated action as proof","ord":5},{"title":"Compose a wordless spread","focus":"Presentation; visual analysis","years":"3-6","minutes":45,"grouping":"Pairs","difficulty":"Medium","look":"The looming forest, the owl's arrival and departure, and the small figures in the final open space","learning":"Make purposeful choices about scale, viewpoint, framing and white space","sequence":"Cover the words and track where the eye travels; compare the emotional effect of a tiny figure and a close-up; identify what the image communicates without repeating narration; sketch two alternative compositions for the same moment","application":"Students create a wordless spread for a moment of waiting or discovery and annotate three compositional choices","notice":"Visual choices guide attention, establish mood and add information that the written sentence does not already state","ord":6},{"title":"What counts as success?","focus":"Synthesising; Determination","years":"2-5","minutes":35,"grouping":"Individual","difficulty":"Medium","look":"The first unanswered calls, the statement that there may not be an owl and the final reflection about hope","learning":"Revise an interpretation as evidence accumulates","sequence":"Record an initial answer to \"What would make this trip successful?\"; revisit it after the first silence; add evidence from the sighting and ending; invite a student who focuses only on finding the owl to explain their reasoning, then ask who can build or challenge with evidence","application":"Students create a before/during/after synthesis showing how their definition of success changed","notice":"Students preserve their earlier view, identify the evidence that changed it and articulate a more nuanced final understanding","ord":7},{"title":"Plan a respectful wildlife observation","focus":"Environmental Sustainability; Making Connections","years":"3-6","minutes":45,"grouping":"Small group","difficulty":"Medium","look":"Pa and the child's quiet movement, listening, calling, brief observation and willingness to let the owl leave","learning":"Connect literary evidence with responsible ways of observing nearby wildlife","sequence":"List what the pair do and do not do; classify each action as observation, possible disturbance or uncertain; identify where the story cannot answer a scientific question; consult an appropriate local wildlife source or school guidance; agree on a low-impact observation protocol","application":"Groups design and justify a short protocol for observing birds or other local animals without touching, feeding or pursuing them","notice":"Recommendations distinguish textual evidence from researched guidance and explain how each choice reduces disturbance","ord":8}]$json$::jsonb) x(title text,focus text,years text,minutes int,grouping text,difficulty text,look text,learning text,sequence text,application text,notice text,ord int);
insert into why_use_bullets(book_id,text,display_order,status) select v,txt,ord,'teacher_reviewed' from jsonb_to_recordset($json$[{"txt":"Exceptional mentor text for sensory imagery, precise word choice and creating a sustained mood","ord":1},{"txt":"Makes inference visible through the child's actions, repeated self-reminders and the warm but largely wordless relationship with Pa","ord":2},{"txt":"Models how a writer can stretch one small experience into a complete narrative by slowing important moments and using patterned pauses","ord":3},{"txt":"Schoenherr's changing scale, viewpoint, darkness and white space deepen suspense and wonder beyond the words alone","ord":4},{"txt":"Supports meaningful inquiry into family experiences, courage and respectful observation of wildlife","ord":5}]$json$::jsonb) x(txt text,ord int);
insert into teaching_resources(book_id,type,title,description,url) select v,type,title,description,url from jsonb_to_recordset($json$[{"type":"PDF","title":"Open school copy","description":"Complete illustrated school copy in Google Drive.","url":"https://drive.google.com/file/d/10gVm-3_GTpicSkPStCILnx9JjGuOh_UU/view?usp=drivesdk"},{"type":"PDF","title":"Open text-only copy","description":"Searchable text-only copy in Google Drive.","url":"https://drive.google.com/file/d/1PfWFjjR873ctQNbBKa7gNfEUSIyZQkCj/view?usp=drivesdk"}]$json$::jsonb) x(type text,title text,description text,url text);
update books set illustrator='Schoenherr, John',publisher='Philomel Books',year_published=1987,text_type='Narrative',genre='Lyrical realistic fiction; small-moment family narrative',year_level_min=0,year_level_max=6,blurb=$blurb$Late one winter night, a child follows Pa through the snowy woods to go owling for the first time. They walk, listen and wait in silence, knowing an owl may never answer. When a Great Horned Owl finally appears, the shared encounter becomes a quiet story about hope, courage, patience and companionship.$blurb$,blurb_status='verified',updated_at=t where id=v;
end $$;
commit;
